import { getRoleShortcutLimit } from "@/lib/roles";
import { useWorkspaceEntitlements } from "@/components/workspace-quota";
import {
  Check,
  Crown,
  ChevronDown,
  FileText,
  Plus,
  Search,
  Upload,
  Undo2,
} from "lucide-react";
import {
  tutorialRoleNote,
  type TutorialHint as Hint,
} from "@/components/tutorial-content";

function Field({
  children,
  dropdown = false,
}: {
  children: React.ReactNode;
  dropdown?: boolean;
}) {
  return (
    <div className="tutorial-mini-field flex items-center justify-between gap-1.5 min-w-0 p-2 [border:1px_solid_var(--border)] rounded-[8px] [background:var(--card)]">
      <span>{children}</span>
      {dropdown && <ChevronDown size={14} />}
    </div>
  );
}
function Chips() {
  return (
    <div className="tutorial-mini-chips flex flex-wrap gap-[5px]">
      <span>Frontend Developer</span>
      <span>Software Engineer Intern</span>
    </div>
  );
}
function ContactRow({ selectable = false }: { selectable?: boolean }) {
  return (
    <div className="tutorial-mini-row flex items-center gap-2">
      {selectable && (
        <span className="tutorial-mini-check grid place-items-center w-4 h-4 shrink-0 rounded-[4px] [background:var(--accent)] text-[var(--color-globals-white)]">
          <Check size={12} />
        </span>
      )}
      <div>
        <strong>Alex</strong>
        <small>Northstar · Frontend Developer</small>
      </div>
    </div>
  );
}

/** Decorative examples only: no inputs, links, handlers, or tab stops. */
export function TutorialHint({
  hint,
  draft = false,
}: {
  hint: Hint;
  draft?: boolean;
}) {
  const access = useWorkspaceEntitlements();
  const cap = access.limits.campaignRecipients;
  const library =
    access.paidGatingEnabled && access.limits.savedTemplates === null;
  const customRoleNote = tutorialRoleNote(access);
  const highlightNote = access.features.previewHighlightColors
    ? "Highlight color picker · 10 colors · saved in this browser"
    : "Cyan highlights · crown for Premium colors";
  let visual: React.ReactNode;
  switch (hint) {
    case "search":
      visual = (
        <>
          <small>Search recipients</small>
          <Field>
            <Search size={14} /> Name, email, or company…
          </Field>
        </>
      );
      break;
    case "template":
      visual = (
        <>
          <small>Template</small>
          <Field dropdown>A first introduction</Field>
          <span className="tutorial-mini-link text-link">Manage Templates</span>
        </>
      );
      break;
    case "roles":
      visual = (
        <>
          <small>Role for Alex</small>
          <Field>Frontend Developer</Field>
          <Chips />
          <span className="tutorial-mini-primary inline-flex items-center justify-center gap-1.5 [align-self:flex-start] rounded-[8px] py-[7px] px-2.5 [background:var(--accent-soft)] text-link font-semibold">
            Preview updates for Alex
          </span>
          <small>{customRoleNote}</small>
        </>
      );
      break;
    case "shortlist":
      visual = (
        <>
          <small>Filter by Job Role · 1 / {cap} selected</small>
          <Field dropdown>All Roles</Field>
          <span className="tutorial-mini-link text-link">Select all</span>
          <ContactRow selectable />
          <span className="tutorial-mini-warning text-[var(--status-warning-text)]!">
            Select yellow recipient · send follow-up
          </span>
        </>
      );
      break;
    case "resume":
      visual = (
        <>
          <small>Personal preview</small>
          <small>
            {!access.features.previewHighlightColors && (
              <Crown className="premium-icon" size={14} aria-hidden="true" />
            )}{" "}
            {highlightNote}
          </small>
          <Field dropdown>Alex · Northstar</Field>
          <p>
            Hi Alex,
            <br />
            Exploring Frontend Developer opportunities…
          </p>
          <div className="tutorial-mini-row flex items-center gap-2">
            <span className="tutorial-mini-check grid place-items-center w-4 h-4 shrink-0 rounded-[4px] [background:var(--accent)] text-[var(--color-globals-white)]">
              <Check size={12} />
            </span>
            Attach PDF
          </div>
          <small>
            <FileText size={14} /> document.pdf · uploaded in Settings
          </small>
        </>
      );
      break;
    case "queue":
      visual = (
        <div className="tutorial-mini-queue flex flex-wrap items-center justify-center gap-3">
          <div
            className={`tutorial-mini-ring grid place-items-center w-25 h-25 shrink-0 rounded-[50%] [background:conic-gradient(_var(--success)_0_24%,_var(--surface)_24%_26%,_var(--queued)_26%_74%,_var(--surface)_74%_76%,_var(--error)_76%_100%)] ${draft ? "is-draft" : ""}`}
          >
            <span>
              <strong>1:20</strong>
              <small>{draft ? "estimated" : "est. left"}</small>
            </span>
          </div>
          <div className="tutorial-mini-legend flex flex-col gap-1">
            <span>
              Sent <b>{draft ? 0 : 1}</b>
            </span>
            <span>
              {draft ? "Selected" : "Queued"} <b>2</b>
            </span>
            <span>
              Failed <b>{draft ? 0 : 1}</b>
            </span>
          </div>
        </div>
      );
      break;
    case "placeholders":
      visual = (
        <>
          <div className="tutorial-mini-chips flex flex-wrap gap-[5px] tutorial-placeholder-chips [font-family:var(--font-sans)]">
            {["{{name}}", "{{company}}", "{{role}}"].map((value) => (
              <span key={value}>{value}</span>
            ))}
          </div>
          <Field>{"Hi {{name}},"}</Field>
          <small>Insert at the message cursor</small>
        </>
      );
      break;
    case "editor":
      visual = (
        <>
          <small>Template name</small>
          <Field>A first introduction</Field>
          <small>Subject</small>
          <Field>{"Exploring {{role}} opportunities"}</Field>
          <small>Message</small>
          <Field>https://example.com/portfolio</Field>
        </>
      );
      break;
    case "preview":
      visual = (
        <>
          <small>Live preview · LIVE</small>
          <Field dropdown>Preview as · Alex</Field>
          <p>
            Hi <mark>Alex</mark>,<br />
            Exploring <mark>Frontend Developer</mark> opportunities at{" "}
            <mark>Northstar</mark>.
          </p>
          <small>
            {!access.features.previewHighlightColors && (
              <Crown className="premium-icon" size={14} aria-hidden="true" />
            )}{" "}
            {highlightNote}
          </small>
          <small>All placeholders are valid</small>
        </>
      );
      break;
    case "saved":
      visual = (
        <>
          <small>Saved templates</small>
          <strong>A first introduction</strong>
          <span className="tutorial-mini-link text-link">
            Edit · Download JSON · Delete
          </span>
          <small>
            {library
              ? "Search library · 10 per page"
              : access.limits.savedTemplates !== null
                ? "1 active template · older templates retained"
                : "Saved templates"}
          </small>
          <Field dropdown>Compose · Template</Field>
        </>
      );
      break;
    case "totals":
      visual = (
        <div className="tutorial-mini-totals flex flex-wrap justify-between gap-2.5">
          {["Sent Today", "In queue", "Replies"].map((label, i) => (
            <div key={label}>
              <small>{label}</small>
              <strong>{[3, 2, 1][i]}</strong>
            </div>
          ))}
        </div>
      );
      break;
    case "statuses":
      visual = (
        <>
          <Field>
            <Search size={14} /> Search recipients or companies…
          </Field>
          <div className="tutorial-mini-chips flex flex-wrap gap-[5px]">
            <span>All</span>
            <span>Sent</span>
            <span className="tutorial-mini-warning text-[var(--status-warning-text)]!">
              Queued
            </span>
            <span className="tutorial-mini-error text-[var(--status-error-text)]!">
              Failed
            </span>
            <span>Replied</span>
            <span>Cancelled</span>
          </div>
          <ContactRow />
          <small>Needs review appears on an uncertain failed attempt</small>
          <small>Template · Sent date and local time · Status</small>
        </>
      );
      break;
    case "uncertain":
      visual = (
        <>
          <small>Usage · Uncertain attempts</small>
          <Field>Needs review · capacity retained</Field>
          <small>Check Gmail Sent, then review History</small>
          <small>Never automatically resent</small>
        </>
      );
      break;
    case "replies":
      visual = (
        <>
          <div className="tutorial-history-actions flex flex-wrap gap-2">
            <span className="tutorial-mini-primary inline-flex items-center justify-center gap-1.5 [align-self:flex-start] rounded-[8px] py-[7px] px-2.5 [background:var(--accent-soft)] text-link font-semibold">
              <Check size={14} /> Mark replied
            </span>
            <span className="tutorial-mini-primary inline-flex items-center justify-center gap-1.5 [align-self:flex-start] rounded-[8px] py-[7px] px-2.5 [background:var(--accent-soft)] text-link font-semibold">
              <Undo2 size={14} /> Undo reply
            </span>
          </div>
          <small>
            {access.features.markReplied
              ? "Undo changes Replied back to Sent"
              : "Reply editing · Premium required"}
          </small>
          <Field>Delivery needs review</Field>
          <small>Failed rows explain the reason</small>
        </>
      );
      break;
    case "history-shortlist":
      visual = (
        <>
          <ContactRow />
          <div className="tutorial-mini-row flex items-center gap-2">
            <span className="tutorial-history-shortlist-icon grid place-items-center shrink-0 w-7.5 h-7.5 [border:1px_solid_var(--border)] rounded-[50%] [background:var(--accent-soft)] text-link">
              {access.features.historyShortlist ? (
                <Plus size={14} />
              ) : (
                <Crown className="premium-icon" size={14} />
              )}
            </span>
            <span>
              {access.features.historyShortlist
                ? "Add to shortlist"
                : "History shortcut · Premium"}
            </span>
          </div>
          <div className="tutorial-mini-row flex items-center gap-2">
            <span className="tutorial-history-shortlist-icon grid place-items-center shrink-0 w-7.5 h-7.5 [border:1px_solid_var(--border)] rounded-[50%] [background:var(--accent-soft)] text-link">
              <Check size={14} />
            </span>
            <span>In shortlist</span>
          </div>
          <small>Review in Compose before sending</small>
        </>
      );
      break;
    case "contacts":
      visual = (
        <>
          <Field>
            <Search size={14} /> Search contacts…
          </Field>
          <ContactRow />
          <small>Company · Job Role · Last Sent</small>
        </>
      );
      break;
    case "contact-form":
      visual = (
        <>
          <small>Email</small>
          <Field>[REDACTED_EMAIL]</Field>
          <small>Name · Company · Job Role</small>
          <Field>Alex · Northstar · Frontend Developer</Field>
          <span className="tutorial-mini-primary inline-flex items-center justify-center gap-1.5 [align-self:flex-start] rounded-[8px] py-[7px] px-2.5 [background:var(--accent-soft)] text-link font-semibold">
            Save Contact
          </span>
          <small>{customRoleNote}</small>
        </>
      );
      break;
    case "import":
      visual = (
        <>
          <div className="tutorial-mini-upload flex flex-col items-center gap-1.5 py-3 px-1.5 [border:1px_dashed_var(--border)] rounded-[8px] text-center">
            <Upload size={20} />
            <span>Drag and drop your CSV here</span>
            <small>
              {access.features.csvImport
                ? "Up to 1 MB / 1,000 rows · or paste a list"
                : "CSV and pasted lists · Premium required"}
            </small>
          </div>
          {access.features.csvImport && (
            <>
              <Field>Bulk Job Role · Frontend Developer</Field>
              <span className="tutorial-mini-primary inline-flex items-center justify-center gap-1.5 [align-self:flex-start] rounded-[8px] py-[7px] px-2.5 [background:var(--accent-soft)] text-link font-semibold">
                Preview Import
              </span>
            </>
          )}
        </>
      );
      break;
    case "import-review":
      visual = (
        <>
          <small>Review your import</small>
          <ContactRow />
          <small>
            {access.features.csvImport
              ? "Correct invalid rows · duplicates skipped"
              : "Import confirmation · Premium required"}
          </small>
          {access.features.csvImport && (
            <span className="tutorial-mini-primary inline-flex items-center justify-center gap-1.5 [align-self:flex-start] rounded-[8px] py-[7px] px-2.5 [background:var(--accent-soft)] text-link font-semibold">
              Confirm import
            </span>
          )}
        </>
      );
      break;
    case "preferences":
      visual = (
        <>
          <small>
            Outreach Preferences · 1–
            {getRoleShortcutLimit(access.effectivePlan)} shortcuts
          </small>
          <Chips />
          <Field>Custom role</Field>
          <small>{customRoleNote}</small>
          <span className="tutorial-mini-primary inline-flex items-center justify-center gap-1.5 [align-self:flex-start] rounded-[8px] py-[7px] px-2.5 [background:var(--accent-soft)] text-link font-semibold">
            Save Preferences
          </span>
        </>
      );
      break;
    case "gmail":
      visual = (
        <>
          <small>Account · Gmail connection</small>
          <Field>[REDACTED_EMAIL]</Field>
          <small>Connected · sending enabled</small>
          <span className="tutorial-mini-primary inline-flex items-center justify-center gap-1.5 [align-self:flex-start] rounded-[8px] py-[7px] px-2.5 [background:var(--accent-soft)] text-link font-semibold">
            Reconnect Gmail
          </span>
          <span className="tutorial-mini-link text-link">
            Manage Access in Google
          </span>
        </>
      );
      break;
    case "pdf":
      visual = (
        <>
          <small>PDF attachment · up to 5 MB</small>
          <Field>
            <FileText size={16} /> document.pdf
          </Field>
          <span className="tutorial-mini-link text-link">
            Download PDF · Replace PDF · Remove
          </span>
          <span className="tutorial-mini-primary inline-flex items-center justify-center gap-1.5 [align-self:flex-start] rounded-[8px] py-[7px] px-2.5 [background:var(--accent-soft)] text-link font-semibold">
            <Upload size={14} /> Save PDF
          </span>
        </>
      );
      break;
    case "limits":
      visual = (
        <>
          <small>Usage</small>
          <Field>
            Batch size <b>Up to {cap}</b>
          </Field>
          <Field>
            Sending capacity{" "}
            <b>
              {access.paidGatingEnabled
                ? "Daily + monthly"
                : "Rolling 24 hours"}
            </b>
          </Field>
          <small>
            {access.paidGatingEnabled
              ? `${access.limits.dailyEmails} daily · ${access.limits.monthlyEmails} monthly · queued emails reserve both`
              : `${access.limits.dailyEmails} emails · sent and queued`}
          </small>
        </>
      );
      break;
    case "subscription":
      visual = (
        <>
          <small>Plan and subscription</small>
          <Field>
            Current access{" "}
            <b>{access.effectivePlan === "PAID" ? "Premium" : "Free"}</b>
          </Field>
          <span className="tutorial-mini-link text-link">
            {access.effectivePlan === "PAID"
              ? "Manage subscription in Settings"
              : "Upgrade to Premium in Usage"}
          </span>
          <span className="tutorial-mini-primary inline-flex items-center justify-center gap-1.5 [align-self:flex-start] rounded-[8px] py-[7px] px-2.5 [background:var(--accent-soft)] text-link font-semibold">
            Refresh subscription status
          </span>
          <small>
            Controls depend on subscription status · no real charges
          </small>
          <small>
            {access.features.blackThemes
              ? "All four themes · Chalk and Obsidian included"
              : "Lavender and Nightbloom · Premium unlocks two more"}
          </small>
          <small>{highlightNote}</small>
          <small>
            {access.features.prioritySupport
              ? "Prioritized email support"
              : "Ordinary support · Premium adds priority"}
          </small>
        </>
      );
      break;
    case "reminders":
      visual = (
        <>
          <small>Follow-up reminders</small>
          <Field dropdown>Remind me after · 7 days</Field>
          <span className="tutorial-mini-primary inline-flex items-center justify-center gap-1.5 [align-self:flex-start] rounded-[8px] py-[7px] px-2.5 [background:var(--accent-soft)] text-link font-semibold">
            Save reminders
          </span>
          <small>
            {access.features.followUpReminders
              ? "Off · 3 · 7 · 14 days"
              : "Premium required"}
          </small>
          <small>
            Review due follow-ups in History · never sends automatically
          </small>
        </>
      );
      break;
    case "data":
      visual = (
        <>
          <small>Your data</small>
          <span className="tutorial-mini-primary inline-flex items-center justify-center gap-1.5 [align-self:flex-start] rounded-[8px] py-[7px] px-2.5 [background:var(--accent-soft)] text-link font-semibold">
            Download my data
          </span>
          <small>Download your PDF attachment separately</small>
          <Field>Danger zone · Delete history · Delete account</Field>
          <small>Confirmation required · cannot be undone</small>
        </>
      );
      break;
  }
  return (
    <div
      className="tutorial-hint flex flex-col gap-[9px] p-3.5 [border:1px_solid_var(--border)] rounded-[12px] [background:var(--surface)] text-[12px] leading-normal wrap-anywhere"
      aria-hidden="true"
    >
      {visual}
    </div>
  );
}
